const r = await tools.exec_command({"cmd":"perl -MJSON::PP -MDigest::SHA=sha256_hex -e '
sub load { my ($f)=@_; open my $h,"<",$f or die "$f: $!"; local $/; my $raw=<$h>; return (decode_json($raw),$raw) }
my ($suite,$suite_raw)=load("tests/cases.json"); my ($r,$report_raw)=load("archive/reports/test_report.json"); open my $ph,"<","src/pricing.py" or die $!; local $/; my $pricing=<$ph>;
die "code binding mismatch\n" unless sha256_hex($pricing) eq $r->{code_revision}; die "suite binding mismatch\n" unless sha256_hex($suite_raw) eq $r->{suite_sha256};
my @rc=@{$r->{cases}}; die "suite/report length mismatch\n" unless @$suite == @rc;
my (%seen,%count); for my $i (0..$#rc) { my $c=$rc[$i]; die "case ID/order mismatch at $i\n" unless $c->{id} eq $suite->[$i]{id}; die "duplicate $c->{id}\n" if $seen{$c->{id}}++; die "invalid status $c->{status}\n" unless $c->{status} eq "pass" || $c->{status} eq "fail"; $count{$c->{status}}++ }
die "total mismatch\n" unless $r->{total} == @rc && $r->{total} == @$suite; die "passed mismatch\n" unless $r->{passed} == ($count{pass}//0); die "failed mismatch\n" unless $r->{failed} == ($count{fail}//0); die "rate mismatch\n" unless abs($r->{pass_rate}-$count{pass}/@rc) < 1e-12;
print "verified total=$r->{total} passed=$r->{passed} failed=$r->{failed} pass_rate=$r->{pass_rate}\n"; for my $c (@rc) { print "$c->{id}\t$c->{status}\t$c->{detail}\n" if $c->{status} eq "fail" }
'","workdir":"/testbed","yield_time_ms":10000,"max_output_tokens":3000}); text(r.output);
